window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-48f83acdc7cbdacf"]={"versions": [{"id": "FIG-48f83acdc7cbdacf", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform (CP), Kommunikationsstack (CAN-Subsystem). Spezifiziert die synchrone Benachrichtigungskette und Fehlerbehandlung bei Detektion eines CAN Bus-Off-Zustands (Transmit Error Counter $TEC > 255$) von der Hardware-Peripherie über den MCAL-Treiber (<code>Can</code>) und die Abstraktionsschicht (<code>CanIf</code>) bis zur zuständigen oberen Schicht (<code>CanIf_User_Cbk</code>, primär <code>CanSM</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Lifelines:</strong></li>\n<li><code>«Peripheral» CanController</code>: Physikalische CAN-Hardware / On-Chip-Controller.</li>\n<li><code>«module» Can</code>: Hardwarenaher MCAL-Treiber (CAN Driver).</li>\n<li><code>«module» CanIf</code>: Hardware-unabhängige CAN-Schnittstelle (CAN Interface).</li>\n<li><code>«interface» CanIf_User_Cbk</code>: Obere Schicht / Anwender-Callback (normativ: <code>CanSM_ControllerBusOff</code>, alternativ CDD).</li>\n<li><strong>APIs & Interaktionen:</strong></li>\n<li><code>BusOff Detection()</code>: Hardware-Signalierung (Interrupt oder Status-Register-Polling).</li>\n<li><code>Set CAN Controller to STOPPED mode, if necessary()</code>: Treiber-Registerzugriff zur Erzwingung des Zustands <code>CAN_CS_STOPPED</code>.</li>\n<li><code>CanIf_ControllerBusOff(uint8 ControllerId)</code>: Normative Treiber-zu-Interface-Callback-API ([SWS_CANIF_00218]).</li>\n<li><code>Change to CAN_CS_STOPPED()</code>: Interne Modusaktualisierung im <code>CanIf</code>.</li>\n<li><code>Reset transmit queue()</code>: Pufferverwaltungs-Aktion im <code>CanIf</code>.</li>\n<li><code>&lt;User_ControllerBusOff&gt;(uint8 ControllerId)</code>: Konfigurierbarer Callback ([SWS_CANIF_00014], typischerweise <code>CanSM_ControllerBusOff</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>CanController</code> wechselt hardwaredenseitig in den Bus-Off-Zustand. Auslösung von <code>BusOff Detection()</code> an das Modul <code>Can</code> (via Bus-Off-ISR oder Polling-Zyklus in <code>Can_MainFunction_BusOff()</code>).</li>\n<li><strong>Hardware-Stopp:</strong> Modul <code>Can</code> prüft den Controller-Status und setzt diesen bei Bedarf aktiv in <code>CAN_CS_STOPPED</code> (<code>Set CAN Controller to STOPPED mode, if necessary()</code>), um jegliche weitere Busaktivität sicher zu unterbinden.</li>\n<li><strong>Notification-Kaskade:</strong> <code>Can</code> ruft synchron <code>CanIf_ControllerBusOff(ControllerId)</code> auf.</li>\n<li><strong>Zustandsübergang & Buffer-Flush:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>CanIf</code> setzt den internen Controller-Zustand auf <code>CAN_CS_STOPPED</code>.</li>\n<li><code>CanIf</code> leert synchron die softwareseitigen Sende-Warteschlangen (<code>Reset transmit queue()</code>). Verhindert das Re-Transmittieren veralteter L-PDUs nach Re-Initialisierung/Neustart des Controllers.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Upper-Layer-Benachrichtigung:</strong> <code>CanIf</code> delegiert das Ereignis synchron an den konfigurierten Callback <code>&lt;User_ControllerBusOff&gt;(ControllerId)</code>.</li>\n<li><strong>Return-Pfad:</strong> Synchroner Rücksprung über alle Schichten bis zur Terminierung des ISR- bzw. Polling-Kontexts.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Ausführungskontext (ISR vs. Task):</strong> Ist <code>CanBusoffProcessing</code> auf <code>INTERRUPT</code> konfiguriert, wird die gesamte Benachrichtigungskette (<code>Can</code> $\\rightarrow$ <code>CanIf</code> $\\rightarrow$ <code>CanSM</code>) im Interrupt-Kontext ausgeführt. <code>&lt;User_ControllerBusOff&gt;</code> darf daher weder blockieren noch zeitkritische Operationen ausführen. Bei <code>POLLING</code> läuft die Kaskade im Kontext von <code>Can_MainFunction_BusOff()</code>.</li>\n<li><strong>Bus-Off-Recovery-Trigger:</strong> Der Callback startet in der <code>CanSM</code> den normativen Bus-Off-Recovery-Zustandsautomaten (BOR-Algorithmus mit schnellen/langsamen Recovery-Timern $T_{BOR\\_1}$ / $T_{BOR\\_2}$).</li>\n<li><strong>Queue-Verhalten & Datenverlust:</strong> Durch <code>Reset transmit queue()</code> werden alle im <code>CanIf</code> gepufferten Tx-PDUs unwiderruflich verworfen (<code>CanIfPublicTxBuffering == TRUE</code>). Höhere Layer (PduR, Com) erhalten keine explizite Cancellation-Benachrichtigung und müssen Timeouts/Re-Transmissionen über Com-Deadline-Monitoring abfangen.</li>\n<li><strong>Konfigurationsparameter:</strong></li>\n<li><code>CanIfDispatchUserCtrlBusOffUL</code>: Konfiguration des Zielmoduls (Standard: <code>CAN_SM</code>, alternativ <code>CDD</code>).</li>\n<li><code>CanIfDispatchUserCtrlBusOffName</code>: Spezifischer Funktionsbezeichner des Callbacks.</li>\n</ul>"}, {"id": "FIG-017ad7c30d29599c", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform (CP), Kommunikationsstack (CAN-Subsystem). Spezifiziert die synchrone Benachrichtigungskette und Fehlerbehandlung bei Detektion eines CAN Bus-Off-Zustands (Transmit Error Counter $TEC > 255$) von der Hardware-Peripherie über den MCAL-Treiber (<code>Can</code>) und die Abstraktionsschicht (<code>CanIf</code>) bis zur zuständigen oberen Schicht (<code>CanIf_User_Cbk</code>, primär <code>CanSM</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Lifelines:</strong></li>\n<li><code>«Peripheral» CanController</code>: Physikalische CAN-Hardware / On-Chip-Controller.</li>\n<li><code>«module» Can</code>: Hardwarenaher MCAL-Treiber (CAN Driver).</li>\n<li><code>«module» CanIf</code>: Hardware-unabhängige CAN-Schnittstelle (CAN Interface).</li>\n<li><code>CanIf_User_Cbk</code>: Obere Schicht / Anwender-Callback (normativ: <code>CanSM_ControllerBusOff</code>, alternativ CDD).</li>\n<li><strong>APIs & Interaktionen:</strong></li>\n<li><code>BusOff Detection()</code>: Hardware-Signalierung (Interrupt oder Status-Register-Polling).</li>\n<li><code>Set CAN Controller to STOPPED mode, if necessary()</code>: Treiber-Registerzugriff zur Erzwingung des Zustands <code>CAN_CS_STOPPED</code>.</li>\n<li><code>CanIf_ControllerBusOff(uint8 ControllerId)</code>: Normative Treiber-zu-Interface-Callback-API ([SWS_CANIF_00218]).</li>\n<li><code>Change to CAN_CS_STOPPED()</code>: Interne Modusaktualisierung im <code>CanIf</code>.</li>\n<li><code>Reset transmit queue()</code>: Pufferverwaltungs-Aktion im <code>CanIf</code>.</li>\n<li><code>&lt;User_ControllerBusOff&gt;(uint8 ControllerId)</code>: Konfigurierbarer Callback ([SWS_CANIF_00014], typischerweise <code>CanSM_ControllerBusOff</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>CanController</code> wechselt hardwaredenseitig in den Bus-Off-Zustand. Auslösung von <code>BusOff Detection()</code> an das Modul <code>Can</code> (via Bus-Off-ISR oder Polling-Zyklus in <code>Can_MainFunction_BusOff()</code>).</li>\n<li><strong>Hardware-Stopp:</strong> Modul <code>Can</code> prüft den Controller-Status und setzt diesen bei Bedarf aktiv in <code>CAN_CS_STOPPED</code> (<code>Set CAN Controller to STOPPED mode, if necessary()</code>), um jegliche weitere Busaktivität sicher zu unterbinden.</li>\n<li><strong>Notification-Kaskade:</strong> <code>Can</code> ruft synchron <code>CanIf_ControllerBusOff(ControllerId)</code> auf.</li>\n<li><strong>Zustandsübergang & Buffer-Flush:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>CanIf</code> setzt den internen Controller-Zustand auf <code>CAN_CS_STOPPED</code>.</li>\n<li><code>CanIf</code> leert synchron die softwareseitigen Sende-Warteschlangen (<code>Reset transmit queue()</code>). Verhindert das Re-Transmittieren veralteter L-PDUs nach Re-Initialisierung/Neustart des Controllers.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Upper-Layer-Benachrichtigung:</strong> <code>CanIf</code> delegiert das Ereignis synchron an den konfigurierten Callback <code>&lt;User_ControllerBusOff&gt;(ControllerId)</code>.</li>\n<li><strong>Return-Pfad:</strong> Synchroner Rücksprung über alle Schichten bis zur Terminierung des ISR- bzw. Polling-Kontexts.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Ausführungskontext (ISR vs. Task):</strong> Ist <code>CanBusoffProcessing</code> auf <code>INTERRUPT</code> konfiguriert, wird die gesamte Benachrichtigungskette (<code>Can</code> $\\rightarrow$ <code>CanIf</code> $\\rightarrow$ <code>CanSM</code>) im Interrupt-Kontext ausgeführt. <code>&lt;User_ControllerBusOff&gt;</code> darf daher weder blockieren noch zeitkritische Operationen ausführen. Bei <code>POLLING</code> läuft die Kaskade im Kontext von <code>Can_MainFunction_BusOff()</code>.</li>\n<li><strong>Bus-Off-Recovery-Trigger:</strong> Der Callback startet in der <code>CanSM</code> den normativen Bus-Off-Recovery-Zustandsautomaten (BOR-Algorithmus mit schnellen/langsamen Recovery-Timern $T_{BOR\\_1}$ / $T_{BOR\\_2}$).</li>\n<li><strong>Queue-Verhalten & Datenverlust:</strong> Durch <code>Reset transmit queue()</code> werden alle im <code>CanIf</code> gepufferten Tx-PDUs unwiderruflich verworfen (<code>CanIfPublicTxBuffering == TRUE</code>). Höhere Layer (PduR, Com) erhalten keine explizite Cancellation-Benachrichtigung und müssen Timeouts/Re-Transmissionen über Com-Deadline-Monitoring abfangen.</li>\n<li><strong>Konfigurationsparameter:</strong></li>\n<li><code>CanIfDispatchUserCtrlBusOffUL</code>: Konfiguration des Zielmoduls (Standard: <code>CAN_SM</code>, alternativ <code>CDD</code>).</li>\n<li><code>CanIfDispatchUserCtrlBusOffName</code>: Spezifischer Funktionsbezeichner des Callbacks.</li>\n</ul>"}, {"id": "FIG-17a6baaf872c46f1", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform (CP), Kommunikationsstack (CAN-Subsystem). Spezifiziert die synchrone Benachrichtigungskette und Fehlerbehandlung bei Detektion eines CAN Bus-Off-Zustands (Transmit Error Counter $TEC > 255$) von der Hardware-Peripherie über den MCAL-Treiber (<code>Can</code>) und die Abstraktionsschicht (<code>CanIf</code>) bis zur zuständigen oberen Schicht (<code>CanIf_User_Cbk</code>, primär <code>CanSM</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Lifelines:</strong></li>\n<li><code>«Peripheral» CanController</code>: Physikalische CAN-Hardware / On-Chip-Controller.</li>\n<li><code>«module» Can</code>: Hardwarenaher MCAL-Treiber (CAN Driver).</li>\n<li><code>«module» CanIf</code>: Hardware-unabhängige CAN-Schnittstelle (CAN Interface).</li>\n<li><code>CanIf_User_Cbk</code>: Obere Schicht / Anwender-Callback (normativ: <code>CanSM_ControllerBusOff</code>, alternativ CDD).</li>\n<li><strong>APIs & Interaktionen:</strong></li>\n<li><code>BusOff Detection()</code>: Hardware-Signalierung (Interrupt oder Status-Register-Polling).</li>\n<li><code>Set CAN Controller to STOPPED mode, if necessary()</code>: Treiber-Registerzugriff zur Erzwingung des Zustands <code>CAN_CS_STOPPED</code>.</li>\n<li><code>CanIf_ControllerBusOff(uint8 ControllerId)</code>: Normative Treiber-zu-Interface-Callback-API ([SWS_CANIF_00218]).</li>\n<li><code>Reset transmit queue()</code>: Pufferverwaltungs-Aktion im <code>CanIf</code>.</li>\n<li><code>&lt;User_ControllerBusOff&gt;(uint8 ControllerId)</code>: Konfigurierbarer Callback ([SWS_CANIF_00014], typischerweise <code>CanSM_ControllerBusOff</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>CanController</code> wechselt hardwaredenseitig in den Bus-Off-Zustand. Auslösung von <code>BusOff Detection()</code> an das Modul <code>Can</code> (via Bus-Off-ISR oder Polling-Zyklus in <code>Can_MainFunction_BusOff()</code>).</li>\n<li><strong>Hardware-Stopp:</strong> Modul <code>Can</code> prüft den Controller-Status und setzt diesen bei Bedarf aktiv in <code>CAN_CS_STOPPED</code> (<code>Set CAN Controller to STOPPED mode, if necessary()</code>), um jegliche weitere Busaktivität sicher zu unterbinden.</li>\n<li><strong>Notification-Kaskade:</strong> <code>Can</code> ruft synchron <code>CanIf_ControllerBusOff(ControllerId)</code> auf.</li>\n<li><strong>Buffer-Flush:</strong> <code>CanIf</code> leert synchron die softwareseitigen Sende-Warteschlangen (<code>Reset transmit queue()</code>). Verhindert das Re-Transmittieren veralteter L-PDUs nach Re-Initialisierung/Neustart des Controllers.</li>\n<li><strong>Upper-Layer-Benachrichtigung:</strong> <code>CanIf</code> delegiert das Ereignis synchron an den konfigurierten Callback <code>&lt;User_ControllerBusOff&gt;(ControllerId)</code>.</li>\n<li><strong>Return-Pfad:</strong> Synchroner Rücksprung über alle Schichten bis zur Terminierung des ISR- bzw. Polling-Kontexts.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Ausführungskontext (ISR vs. Task):</strong> Ist <code>CanBusoffProcessing</code> auf <code>INTERRUPT</code> konfiguriert, wird die gesamte Benachrichtigungskette (<code>Can</code> $\\rightarrow$ <code>CanIf</code> $\\rightarrow$ <code>CanSM</code>) im Interrupt-Kontext ausgeführt. <code>&lt;User_ControllerBusOff&gt;</code> darf daher weder blockieren noch zeitkritische Operationen ausführen. Bei <code>POLLING</code> läuft die Kaskade im Kontext von <code>Can_MainFunction_BusOff()</code>.</li>\n<li><strong>Bus-Off-Recovery-Trigger:</strong> Der Callback startet in der <code>CanSM</code> den normativen Bus-Off-Recovery-Zustandsautomaten (BOR-Algorithmus mit schnellen/langsamen Recovery-Timern $T_{BOR\\_1}$ / $T_{BOR\\_2}$).</li>\n<li><strong>Queue-Verhalten & Datenverlust:</strong> Durch <code>Reset transmit queue()</code> werden alle im <code>CanIf</code> gepufferten Tx-PDUs unwiderruflich verworfen (<code>CanIfPublicTxBuffering == TRUE</code>). Höhere Layer (PduR, Com) erhalten keine explizite Cancellation-Benachrichtigung und müssen Timeouts/Re-Transmissionen über Com-Deadline-Monitoring abfangen.</li>\n<li><strong>Konfigurationsparameter:</strong></li>\n<li><code>CanIfDispatchUserCtrlBusOffUL</code>: Konfiguration des Zielmoduls (Standard: <code>CAN_SM</code>, alternativ <code>CDD</code>).</li>\n<li><code>CanIfDispatchUserCtrlBusOffName</code>: Spezifischer Funktionsbezeichner des Callbacks.</li>\n</ul>"}, {"id": "FIG-dbcd1d9253670e06", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform (CP), Kommunikationsstack (CAN-Subsystem). Spezifiziert die synchrone Benachrichtigungskette und Fehlerbehandlung bei Detektion eines CAN Bus-Off-Zustands (Transmit Error Counter $TEC > 255$) von der Hardware-Peripherie über den MCAL-Treiber (<code>Can</code>) und die Abstraktionsschicht (<code>CanIf</code>) bis zur zuständigen oberen Schicht (<code>CanIf_User_Cbk</code>, primär <code>CanSM</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Lifelines:</strong></li>\n<li><code>«Peripheral» CanController</code>: Physikalische CAN-Hardware / On-Chip-Controller.</li>\n<li><code>«module» Can</code>: Hardwarenaher MCAL-Treiber (CAN Driver).</li>\n<li><code>«module» CanIf</code>: Hardware-unabhängige CAN-Schnittstelle (CAN Interface).</li>\n<li><code>&lt;User_ControllerBusOff&gt;</code>: Obere Schicht / Anwender-Callback (normativ: <code>CanSM_ControllerBusOff</code>, alternativ CDD).</li>\n<li><strong>APIs & Interaktionen:</strong></li>\n<li><code>BusOff Detection()</code>: Hardware-Signalierung (Interrupt oder Status-Register-Polling).</li>\n<li><code>Set CAN Controller to STOPPED mode, if necessary()</code>: Treiber-Registerzugriff zur Erzwingung des Zustands <code>CAN_CS_STOPPED</code>.</li>\n<li><code>CanIf_ControllerBusOff(uint8 ControllerId)</code>: Normative Treiber-zu-Interface-Callback-API ([SWS_CANIF_00218]).</li>\n<li><code>Reset transmit queue()</code>: Pufferverwaltungs-Aktion im <code>CanIf</code>.</li>\n<li><code>&lt;User_ControllerBusOff&gt;(uint8 ControllerId)</code>: Konfigurierbarer Callback ([SWS_CANIF_00014], typischerweise <code>CanSM_ControllerBusOff</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>CanController</code> wechselt hardwaredenseitig in den Bus-Off-Zustand. Auslösung von <code>BusOff Detection()</code> an das Modul <code>Can</code> (via Bus-Off-ISR oder Polling-Zyklus in <code>Can_MainFunction_BusOff()</code>).</li>\n<li><strong>Hardware-Stopp:</strong> Modul <code>Can</code> prüft den Controller-Status und setzt diesen bei Bedarf aktiv in <code>CAN_CS_STOPPED</code> (<code>Set CAN Controller to STOPPED mode, if necessary()</code>), um jegliche weitere Busaktivität sicher zu unterbinden.</li>\n<li><strong>Notification-Kaskade:</strong> <code>Can</code> ruft synchron <code>CanIf_ControllerBusOff(ControllerId)</code> auf.</li>\n<li><strong>Buffer-Flush:</strong> <code>CanIf</code> leert synchron die softwareseitigen Sende-Warteschlangen (<code>Reset transmit queue()</code>). Verhindert das Re-Transmittieren veralteter L-PDUs nach Re-Initialisierung/Neustart des Controllers.</li>\n<li><strong>Upper-Layer-Benachrichtigung:</strong> <code>CanIf</code> delegiert das Ereignis synchron an den konfigurierten Callback <code>&lt;User_ControllerBusOff&gt;(ControllerId)</code>.</li>\n<li><strong>Return-Pfad:</strong> Synchroner Rücksprung über alle Schichten bis zur Terminierung des ISR- bzw. Polling-Kontexts.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Ausführungskontext (ISR vs. Task):</strong> Ist <code>CanBusoffProcessing</code> auf <code>INTERRUPT</code> konfiguriert, wird die gesamte Benachrichtigungskette (<code>Can</code> $\\rightarrow$ <code>CanIf</code> $\\rightarrow$ <code>CanSM</code>) im Interrupt-Kontext ausgeführt. <code>&lt;User_ControllerBusOff&gt;</code> darf daher weder blockieren noch zeitkritische Operationen ausführen. Bei <code>POLLING</code> läuft die Kaskade im Kontext von <code>Can_MainFunction_BusOff()</code>.</li>\n<li><strong>Bus-Off-Recovery-Trigger:</strong> Der Callback startet in der <code>CanSM</code> den normativen Bus-Off-Recovery-Zustandsautomaten (BOR-Algorithmus mit schnellen/langsamen Recovery-Timern $T_{BOR\\_1}$ / $T_{BOR\\_2}$).</li>\n<li><strong>Queue-Verhalten & Datenverlust:</strong> Durch <code>Reset transmit queue()</code> werden alle im <code>CanIf</code> gepufferten Tx-PDUs unwiderruflich verworfen (<code>CanIfPublicTxBuffering == TRUE</code>). Höhere Layer (PduR, Com) erhalten keine explizite Cancellation-Benachrichtigung und müssen Timeouts/Re-Transmissionen über Com-Deadline-Monitoring abfangen.</li>\n<li><strong>Konfigurationsparameter:</strong></li>\n<li><code>CanIfDispatchUserCtrlBusOffUL</code>: Konfiguration des Zielmoduls (Standard: <code>CAN_SM</code>, alternativ <code>CDD</code>).</li>\n<li><code>CanIfDispatchUserCtrlBusOffName</code>: Spezifischer Funktionsbezeichner des Callbacks.</li>\n</ul>"}, {"id": "FIG-f2c5632335ce93d0", "releases": ["R21-11", "R22-11", "R23-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform (CP), Kommunikationsstack (CAN-Subsystem). Spezifiziert die synchrone Benachrichtigungskette und Fehlerbehandlung bei Detektion eines CAN Bus-Off-Zustands (Transmit Error Counter $TEC > 255$) von der Hardware-Peripherie über den MCAL-Treiber (<code>Can</code>) und die Abstraktionsschicht (<code>CanIf</code>) bis zur zuständigen oberen Schicht (<code>CanIf_User_Cbk</code>, primär <code>CanSM</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Lifelines:</strong></li>\n<li><code>«Peripheral» CanController</code>: Physikalische CAN-Hardware / On-Chip-Controller.</li>\n<li><code>«module» Can</code>: Hardwarenaher MCAL-Treiber (CAN Driver).</li>\n<li><code>«module» CanIf</code>: Hardware-unabhängige CAN-Schnittstelle (CAN Interface).</li>\n<li><code>&lt;User_ControllerBusOff&gt;</code>: Obere Schicht / Anwender-Callback (normativ: <code>CanSM_ControllerBusOff</code>, alternativ CDD).</li>\n<li><strong>APIs & Interaktionen:</strong></li>\n<li><code>BusOff Detection()</code>: Hardware-Signalierung (Interrupt oder Status-Register-Polling).</li>\n<li><code>Set CAN Controller to STOPPED mode, if necessary()</code>: Treiber-Registerzugriff zur Erzwingung des Zustands <code>CAN_CS_STOPPED</code>.</li>\n<li><code>CanIf_ControllerBusOff(uint8 ControllerId)</code>: Normative Treiber-zu-Interface-Callback-API ([SWS_CANIF_00218]).</li>\n<li><code>Reset transmit queue()</code>: Pufferverwaltungs-Aktion im <code>CanIf</code>.</li>\n<li><code>&lt;User_ControllerBusOff&gt;(uint8 ControllerId)</code>: Konfigurierbarer Callback ([SWS_CANIF_00014], typischerweise <code>CanSM_ControllerBusOff</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>CanController</code> wechselt hardwaredenseitig in den Bus-Off-Zustand. Auslösung von <code>BusOff Detection()</code> an das Modul <code>Can</code> (via Bus-Off-ISR oder Polling-Zyklus in <code>Can_MainFunction_BusOff()</code>).</li>\n<li><strong>Hardware-Stopp:</strong> Modul <code>Can</code> prüft den Controller-Status und setzt diesen bei Bedarf aktiv in <code>CAN_CS_STOPPED</code> (<code>Set CAN Controller to STOPPED mode, if necessary()</code>), um jegliche weitere Busaktivität sicher zu unterbinden.</li>\n<li><strong>Notification-Kaskade:</strong> <code>Can</code> ruft synchron <code>CanIf_ControllerBusOff(ControllerId)</code> auf.</li>\n<li><strong>Buffer-Flush:</strong> <code>CanIf</code> leert synchron die softwareseitigen Sende-Warteschlangen (<code>Reset transmit queue()</code>). Verhindert das Re-Transmittieren veralteter L-PDUs nach Re-Initialisierung/Neustart des Controllers.</li>\n<li><strong>Upper-Layer-Benachrichtigung:</strong> <code>CanIf</code> delegiert das Ereignis synchron an den konfigurierten Callback <code>&lt;User_ControllerBusOff&gt;(ControllerId)</code>.</li>\n<li><strong>Return-Pfad:</strong> Synchroner Rücksprung über alle Schichten bis zur Terminierung des ISR- bzw. Polling-Kontexts.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Ausführungskontext (ISR vs. Task):</strong> Ist <code>CanBusoffProcessing</code> auf <code>INTERRUPT</code> konfiguriert, wird die gesamte Benachrichtigungskette (<code>Can</code> $\\rightarrow$ <code>CanIf</code> $\\rightarrow$ <code>CanSM</code>) im Interrupt-Kontext ausgeführt. <code>&lt;User_ControllerBusOff&gt;</code> darf daher weder blockieren noch zeitkritische Operationen ausführen. Bei <code>POLLING</code> läuft die Kaskade im Kontext von <code>Can_MainFunction_BusOff()</code>.</li>\n<li><strong>Bus-Off-Recovery-Trigger:</strong> Der Callback startet in der <code>CanSM</code> den normativen Bus-Off-Recovery-Zustandsautomaten (BOR-Algorithmus mit schnellen/langsamen Recovery-Timern $T_{BOR\\_1}$ / $T_{BOR\\_2}$).</li>\n<li><strong>Queue-Verhalten & Datenverlust:</strong> Durch <code>Reset transmit queue()</code> werden alle im <code>CanIf</code> gepufferten Tx-PDUs unwiderruflich verworfen (<code>CanIfPublicTxBuffering == TRUE</code>). Höhere Layer (PduR, Com) erhalten keine explizite Cancellation-Benachrichtigung und müssen Timeouts/Re-Transmissionen über Com-Deadline-Monitoring abfangen.</li>\n<li><strong>Konfigurationsparameter:</strong></li>\n<li><code>CanIfDispatchUserCtrlBusOffUL</code>: Konfiguration des Zielmoduls (Standard: <code>CAN_SM</code>, alternativ <code>CDD</code>).</li>\n<li><code>CanIfDispatchUserCtrlBusOffName</code>: Spezifischer Funktionsbezeichner des Callbacks.</li>\n</ul>"}], "trans": [{"from": "FIG-48f83acdc7cbdacf", "to": "FIG-017ad7c30d29599c", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Lifeline <code>«interface» CanIf_User_Cbk</code>: Stereotyp <code>«interface»</code> wurde entfernt (Bezeichnung nun <code>CanIf_User_Cbk</code>).</li>\n</ul>"}, {"from": "FIG-017ad7c30d29599c", "to": "FIG-17a6baaf872c46f1", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Lifeline <code>CanIf</code>: Der interne Selbstaufruf <code>Change to CAN_CS_STOPPED()</code> wurde entfernt.</li>\n</ul>"}, {"from": "FIG-17a6baaf872c46f1", "to": "FIG-f2c5632335ce93d0", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Lifeline <code>CanIf_User_Cbk</code>: Umbenannt in <code>&lt;User_ControllerBusOff&gt;</code>.</li>\n</ul>"}, {"from": "FIG-f2c5632335ce93d0", "to": "FIG-dbcd1d9253670e06", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
